      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    });
  const extraConfig = (extra: string[], overrides: Partial<SessionConfig> = {}): SessionConfig => ({
    password: sessionConfig.password,
    extraUnsealPasswords: extra,
    generateId: () => "new",
    ...overrides,
  });
  const cookieValue = (res: Response) =>
    decodeURIComponent(
      res.headers.getSetCookie().find((c) => c.startsWith("h3="))!.match(/h3=([^;]+)/)![1],
    );
  const registerRead = (path: string, config: SessionConfig) => {
    t.app.get(path, async (event) => ({ session: await getSession(event, config) }));
  };

