    const withoutExtra: SessionConfig = { password: sessionConfig.password };
    const withExtra: SessionConfig = {
      password: sessionConfig.password,
      extraUnsealPasswords: [extraPassword],
    };
    const invalid: SessionConfig = {
      password: sessionConfig.password,
      // @ts-expect-error extraUnsealPasswords must be an array of strings
      extraUnsealPasswords: "uma-string",
    };
    expect([withoutExtra, withExtra, invalid]).toHaveLength(3);
  });

  it("seals new sessions only with password", async () => {
