      id: "new",
    });
    await expect(unseal(sealed, extraPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("opens sessions with any password in the list", async () => {
    registerRead("/extra-read", extraConfig([extraPassword, olderPassword]));
    const expected = { id: "sess-b", createdAt, data: { foo: "sess-b" } };

    const fromOlder = await t.fetch("/extra-read", {
      headers: { Cookie: `h3=${await sealWith(olderPassword, "sess-b")}` },
    });
    expect(await fromOlder.json()).toMatchObject({ session: expected });

    const fromPassword = await t.fetch("/extra-read", {
      headers: { Cookie: `h3=${await sealWith(sessionConfig.password, "sess-b")}` },
    });
    expect(await fromPassword.json()).toMatchObject({ session: expected });

    const fromUnknown = await t.fetch("/extra-read", {
      headers: { Cookie: `h3=${await sealWith(unknownPassword, "sess-c")}` },
    });
    expect(await fromUnknown.json()).toMatchObject({ session: { id: "new", data: {} } });
  });

  it("reads sessions sealed with an extra password from the session header", async () => {
    registerRead("/extra-header", extraConfig([extraPassword]));
    const res = await t.fetch("/extra-header", {
      headers: { "x-h3-session": await sealWith(extraPassword, "sess-a") },
    });
    expect(await res.json()).toMatchObject({
      session: { id: "sess-a", data: { foo: "sess-a" } },
    });
  });

  it("updateSession reads an extra-password cookie and seals with password", async () => {
    t.app.post("/extra-update", async (event) => {
      const session = await updateSession(event, extraConfig([extraPassword]), { bar: "new" });
      return { data: session.data };
    });
    const res = await t.fetch("/extra-update", {
      method: "POST",
      headers: { Cookie: `h3=${await sealWith(extraPassword, "sess-a")}` },
    });
    expect(await res.json()).toMatchObject({ data: { foo: "sess-a", bar: "new" } });
    expect(
      await unseal(cookieValue(res), sessionConfig.password, sealDefaults),
    ).toMatchObject({ id: "sess-a", data: { foo: "sess-a", bar: "new" } });
  });

  it("keeps the token format when no extra passwords are set", async () => {
    t.app.get("/plain-new", async (event) => {
      await useSession(event, { password: sessionConfig.password });
      return { ok: true };
    });
    t.app.get("/empty-new", async (event) => {
      await useSession(event, extraConfig([]));
      return { ok: true };
    });
    for (const path of ["/plain-new", "/empty-new"]) {
      const parts = cookieValue(await t.fetch(path)).split("*");
      expect(parts).toHaveLength(8);
      expect(parts[0]).toBe("Fe26.2");
      expect(parts[1]).toBe("");
    }
  });

  it("opens legacy sessions sealed with an extra password and reseals them", async () => {
    registerRead("/extra-legacy", extraConfig([extraPassword]));
    const res = await t.fetch("/extra-legacy", {
      headers: { Cookie: `h3=${await sealLegacyWith(extraPassword, "legacy-a")}` },
    });
    expect(await res.json()).toMatchObject({
      session: { id: "legacy-a", data: { foo: "legacy-a" } },
    });
    expect(res.headers.getSetCookie()).toHaveLength(1);
    expect(
      await unseal(cookieValue(res), sessionConfig.password, sealDefaults),
    ).toMatchObject({ id: "legacy-a" });
  });

  it("treats legacy sessions sealed with an extra password as missing with legacySealFallback: false", async () => {
    registerRead("/extra-legacy-strict", extraConfig([extraPassword], { legacySealFallback: false }));
    const res = await t.fetch("/extra-legacy-strict", {
      headers: { Cookie: `h3=${await sealLegacyWith(extraPassword, "legacy-a")}` },
    });
    const body = await res.json();
    expect(body.session.id).not.toBe("legacy-a");
    expect(body.session.data).toEqual({});
  });

  it("reseals extra-password cookies with password, and does not reseal header sessions", async () => {
    registerRead("/extra-migrate", extraConfig([extraPassword]));
    registerRead("/plain-read", { password: sessionConfig.password });
    const res = await t.fetch("/extra-migrate", {
      headers: { Cookie: `h3=${await sealWith(extraPassword, "sess-m")}` },
    });
    const resealed = cookieValue(res);
    expect(await unseal(resealed, sessionConfig.password, sealDefaults)).toMatchObject({
      id: "sess-m",
    });
    await expect(unseal(resealed, extraPassword, sealDefaults)).rejects.toThrow("Bad hmac value");

    const plain = await t.fetch("/plain-read", { headers: { Cookie: `h3=${resealed}` } });
    expect(await plain.json()).toMatchObject({
      session: { id: "sess-m", data: { foo: "sess-m" } },
    });

    const fromHeader = await t.fetch("/extra-migrate", {
      headers: { "x-h3-session": await sealWith(extraPassword, "sess-h") },
    });
    expect(fromHeader.headers.getSetCookie()).toHaveLength(0);
  });

  it("validates extraUnsealPasswords before reading the cookie", async () => {
    t.app.get("/extra-invalid", async (event) => {
      const errors: (string | null)[] = [];
      for (const extra of [["curta"], [""], []]) {
